/* eslint-disable */
/* Immunology OS cell atlas (original). */
export interface Cell {
  id: string; name: string; lineage: string; lineageLabel: string; tagline: string; summary: string; story: string;
  simpleRole: string; advanced: string[]; clinical: string; analogyBreak: string; icon: string;
}
export const LEGACY: { cells: Cell[]; cellKG: Record<string, string[]>; tcrSteps: any[]; tcrPerturbations: any[]; [k: string]: unknown } = {"cells": [{"id": "neutrophil", "name": "Neutrophil", "tagline": "The rapid-response patrol", "lineage": "myeloid", "lineageLabel": "Myeloid", "summary": "The most abundant white blood cell. First to arrive at infection sites, fights hard, dies fast, and leaves a trail of destruction.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"16\" cy=\"16\" r=\"10\"/><circle cx=\"12\" cy=\"14\" r=\"3\" fill=\"currentColor\" opacity=\"0.3\"/><circle cx=\"20\" cy=\"18\" r=\"2.5\" fill=\"currentColor\" opacity=\"0.3\"/><path d=\"M16 6v4M16 22v4M6 16h4M22 16h4\" stroke-linecap=\"round\"/></svg>", "story": "Picture a SWAT team that gets the call at 3 AM. They arrive within minutes, fast, aggressive, and not asking questions. They shoot first (degranulation), throw gas grenades (reactive oxygen species), and even cast nets of their own DNA to trap intruders (NETs). After the fight, they die, becoming the pus you see in wounds. Their sacrifice clears the infection, but also signals the next wave to come in and clean up.", "simpleRole": "First-responder white blood cell. Rushes to bacterial and fungal infections within minutes. Engulfs and kills microbes (phagocytosis), releases toxic chemicals, and casts DNA nets (NETs) to trap pathogens.", "advanced": ["Derived from myeloid progenitors in bone marrow; ~10¹¹ produced daily", "Pattern recognition: TLRs, NOD-like receptors, Fc receptors, complement receptors", "Killing mechanisms: NADPH oxidase respiratory burst (ROS), myeloperoxidase, defensins, lactoferrin", "NETosis: release of chromatin decorated with antimicrobial proteins (MPO, NE, cathelicidin)", "Short-lived: hours in circulation (typically 6-8 hours); can survive longer in tissues, especially during inflammation", "Granulopoiesis regulated by G-CSF; emergency granulopoiesis during severe infection", "Trained immunity: epigenetic reprogramming of precursors after infection/vaccination (histone modifications at enhancers of immune genes)", "Resolution: undergo apoptosis (not necrosis), cleared by macrophages via efferocytosis, failure drives chronic inflammation", "Immunometabolism: shift from oxidative phosphorylation to glycolysis upon activation (Warburg-like)", "Subversion: some pathogens (S. aureus, Pseudomonas) exploit NETs or resist neutrophil killing"], "clinical": "Neutropenia (low neutrophils) → severe, recurrent infections. Chronic granulomatous disease (defective NADPH oxidase) → recurrent abscesses. NET excess → thrombosis, autoimmune disease (SLE, ANCA vasculitis).", "analogyBreak": "The \"shoot first\" metaphor is useful but incomplete. Neutrophils also actively resolve inflammation, modulate adaptive immunity, and can even perform antigen presentation. They are not just cannon fodder. They are sophisticated communicators."}, {"id": "macrophage", "name": "Macrophage", "tagline": "The street cleaner & sentinel", "lineage": "myeloid", "lineageLabel": "Myeloid", "summary": "Tissue-resident giant cells that eat debris, present antigens, and orchestrate local inflammation. They are the city's janitors, sentinels, and local commanders rolled into one.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><path d=\"M16 4c-6 0-11 5-11 11s5 13 11 13 11-7 11-13-5-11-11-11z\" opacity=\"0.3\"/><circle cx=\"16\" cy=\"16\" r=\"8\"/><path d=\"M12 14h8M12 18h5\" stroke-linecap=\"round\"/><circle cx=\"22\" cy=\"10\" r=\"2\" fill=\"currentColor\" opacity=\"0.4\"/></svg>", "story": "Meet the city's longest-serving civil servant. By day, they sweep the streets, clearing dead cells, dust, and debris. But they are also the neighborhood watch, constantly tasting their surroundings for danger. When they spot trouble, they don't just fight: they send out alarm signals (cytokines) that wake up the entire district. And when the intelligence officers (dendritic cells) need information, macrophages share what they've found.", "simpleRole": "Large phagocytic cell resident in every tissue. Engulfs dead cells, pathogens, and debris. Releases cytokines to recruit other immune cells. Presents antigen to T cells. Key player in both starting and resolving inflammation.", "advanced": ["Derived from yolk sac progenitors (tissue-resident) or bone marrow monocytes (inflammatory)", "Tissue-specific identities: Kupffer cells (liver), microglia (brain), alveolar macrophages (lung), osteoclasts (bone), Langerhans cells (skin, macrophage-like ontogeny, often classified as dendritic cells)", "Activation spectrum: historical M1/M2 paradigm (M1: classical, pro-inflammatory, IFN-γ + LPS; M2: alternative, anti-inflammatory/wound repair, IL-4/IL-13), useful teaching shorthand, not a true binary; in vivo activation is a continuous spectrum", "Pattern recognition: TLRs, NLRs, RLRs, CLRs, scavenger receptors (CD36, SR-A)", "Antigen presentation: MHC II + co-stimulation (CD80/86) to CD4+ T cells", "Efferocytosis: clearance of apoptotic cells, prevents autoimmunity by avoiding release of intracellular contents", "Cytokine production: TNF-α, IL-1β, IL-6, IL-12, IL-10, TGF-β (context-dependent)", "Tissue repair: production of VEGF, PDGF, TGF-β → angiogenesis and fibrosis", "Immunometabolism: M1 relies on glycolysis; M2 on oxidative phosphorylation and fatty acid oxidation", "Trained immunity: epigenetic and metabolic reprogramming enables enhanced secondary responses (β-glucan, BCG)", "Self-renewal: tissue-resident macrophages can proliferate locally without bone marrow input"], "clinical": "Macrophage dysfunction → chronic granulomatous diseases, atherosclerosis (foam cells), fibrosis, tumour-associated macrophages (TAMs) promote cancer progression. M1/M2 imbalance drives chronic inflammation and autoimmune disease.", "analogyBreak": "The \"street cleaner\" metaphor captures phagocytosis but underrepresents macrophages' active roles in tissue remodelling, metabolic regulation, and development. They are not passive janitors. They are tissue architects that shape organ function."}, {"id": "dendritic", "name": "Dendritic Cell", "tagline": "The intelligence officer", "lineage": "myeloid", "lineageLabel": "Myeloid", "summary": "The bridge between innate and adaptive immunity. They patrol tissues, capture enemies, and carry intelligence to headquarters (lymph nodes) to brief the T cells.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"16\" cy=\"16\" r=\"5\"/><path d=\"M16 11V6M16 21v5M11 16H6M21 16h5M12.5 12.5l-3.5-3.5M19.5 19.5l3.5 3.5M12.5 19.5l-3.5 3.5M19.5 12.5l3.5-3.5\" stroke-linecap=\"round\"/></svg>", "story": "Imagine a deep-cover operative who speaks every language. They patrol the borders (skin, gut, lungs), blending in, sampling the environment. When they encounter a pathogen, they don't just fight. They collect evidence. Then they travel to headquarters (lymph nodes), undergo a dramatic transformation, and present their findings to the T cells. Without this briefing, the adaptive immune system cannot respond. They are the only cell that can activate naive T cells.", "simpleRole": "Professional antigen-presenting cell (APC). Patrols peripheral tissues, captures pathogens, processes them into peptide fragments, migrates to lymph nodes, and presents antigens to naive T cells via MHC. The principal/specialized APC for priming naive T cells, the critical bridge between innate and adaptive immunity.", "advanced": ["Subsets: conventional DCs (cDC1: cross-presentation, anti-viral/cancer; cDC2: anti-bacterial/fungal), plasmacytoid DCs (pDCs: type I IFN production), monocyte-derived DCs (moDCs, inflammatory)", "Maturation: immature (phagocytic, migratory) → mature (high MHC, co-stimulation, cytokine production)", "Cross-presentation: ability to present exogenous antigens on MHC I, critical for CD8+ T cell priming against viruses and tumours", "Pattern recognition: TLRs, C-type lectins (DEC-205, CLEC9A, DNGR-1), NLRs", "Migration: CCR7-driven chemotaxis to lymph nodes upon maturation", "Cytokine output: IL-12 (Th1), IL-23 (Th17), type I IFN (anti-viral)", "Tolerogenic DCs: can induce tolerance rather than immunity (peripheral tolerance, oral tolerance)", "Development: Flt3L-dependent; distinct from monocytes and macrophages (different transcription factors: IRF8, IRF4, BATF3)", "Cancer: tumour-infiltrating DCs often dysfunctional; immunotherapy aims to restore DC function", "mRNA vaccines: lipid nanoparticles deliver mRNA to multiple cell types; DCs and other APCs that take up mRNA present antigen and prime T cells. This is the basis of mRNA vaccine immunogenicity"], "clinical": "DC dysfunction → immunodeficiency, poor vaccine response. DCs are targets for checkpoint immunotherapy. Tolerogenic DCs being explored for autoimmune disease treatment. mRNA vaccines (COVID-19) work through DC antigen presentation.", "analogyBreak": "The \"intelligence officer\" metaphor is strong but implies a single, passive briefing. DCs actively shape the type of immune response (Th1 vs Th2 vs Th17 vs tolerance) through their cytokine output and co-stimulatory molecule expression. They don't just deliver information, they bias the interpretation."}, {"id": "nk", "name": "Natural Killer Cell", "tagline": "The corruption inspector", "lineage": "innate", "lineageLabel": "Innate Lymphoid", "summary": "Innate lymphocyte that kills virus-infected and cancerous cells without needing prior sensitization. They inspect every cell for signs of corruption.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"16\" cy=\"16\" r=\"10\"/><path d=\"M11 11l4 4M21 21l-4-4M11 21l4-4M21 11l-4 4\" stroke-linecap=\"round\"/><circle cx=\"16\" cy=\"16\" r=\"2\" fill=\"currentColor\"/></svg>", "story": "Think of a health inspector who visits every factory in the city, checking IDs. Every cell must display a \"self\" badge (MHC I) to prove it belongs. If a cell is infected or turned cancerous, it stops showing the badge, or shows a corrupted one. The NK cell doesn't need to be told who the enemy is. It simply checks: badge present? Badge missing? If the badge is missing, the cell is destroyed. No trial, no deliberation, just immediate elimination.", "simpleRole": "Cytotoxic innate lymphocyte. Kills virus-infected cells and tumour cells without prior antigen encounter. Uses the \"missing-self\" hypothesis: detects absence of MHC I on target cells. Also produces IFN-γ to activate macrophages.", "advanced": ["No rearranged antigen receptor, unlike T and B cells; classified as cytotoxic group 1 ILCs, distinct from helper-like ILC1s", "Recognition: \"missing-self\" (reduced MHC I) via inhibitory receptors (KIRs in humans, Ly49 in mice)", "Activating receptors: NKG2D (stress ligands: MICA, MICB), NCRs (NKp30, NKp44, NKp46), CD16 (ADCC)", "Killing: perforin/granzyme, FasL/TRAIL death receptor pathways", "Antibody-dependent cellular cytotoxicity (ADCC): CD16 binds Fc of IgG-opsonized targets", "Cytokine production: IFN-γ, TNF-α, activates macrophages, shapes Th1 responses", "Education/licensing: NK cells must encounter self-MHC during development to become functional (\"arming\")", "Memory-like NK cells: certain viral exposures (CMV) generate adaptive NK cell populations", "Tissue-resident NK cells: uterine NK cells (pregnancy), liver NK cells have distinct phenotypes", "Checkpoint receptors: NKG2A, TIGIT, CD96, targets for cancer immunotherapy"], "clinical": "NK cell deficiency → severe, recurrent viral infections (especially herpesviruses). NK cells are critical for early cancer surveillance. Checkpoint inhibitors targeting NKG2A and TIGIT aim to unleash NK cells in cancer. Uterine NK cells are essential for placental development.", "analogyBreak": "The \"badge check\" metaphor captures missing-self but not the full complexity. NK cells also recognize specific stress-induced ligands (NKG2D), perform ADCC, and are educated through self-interactions. They are not simply reactive. They have \"licensed\" receptors that require tuning."}, {"id": "bcell", "name": "B Cell", "tagline": "The weapons designer", "lineage": "lymphoid", "lineageLabel": "Lymphoid", "summary": "Lymphocyte that recognizes specific antigens and produces antibodies. Part researcher, part factory manager. They design precision weapons against each new threat.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"16\" cy=\"16\" r=\"8\"/><path d=\"M12 12l8 8M20 12l-8 8\" stroke-linecap=\"round\"/><circle cx=\"16\" cy=\"16\" r=\"2\" fill=\"currentColor\"/></svg>", "story": "Picture a defence research lab. When a new pathogen arrives, the B cell studies it, then designs a precision weapon, an antibody. That locks onto that exact enemy. Some B cells become mass-production factories (plasma cells), churning out millions of identical weapons. Others become memory cells, filing away the blueprint so next time, the weapon is ready in hours, not weeks.", "simpleRole": "Lymphocyte that expresses a unique B cell receptor (BCR, membrane immunoglobulin + CD79a/CD79b signalling chains) for antigen recognition. Upon activation, differentiates into plasma cells (antibody factories) or memory B cells. Essential for humoral immunity.", "advanced": ["Development: bone marrow, from common lymphoid progenitor; V(D)J recombination creates unique BCR", "BCR = membrane-bound immunoglobulin (IgM + IgD on naive B cells, via alternative splicing)", "Activation: T-dependent (protein antigens, requires Tfh help, germinal centre) or T-independent (polysaccharides, no T help)", "Germinal centre: somatic hypermutation (SHM) in V region → affinity maturation; class-switch recombination (CSR) → IgG, IgA, IgE (IgD is co-expressed with IgM by alternative splicing in naive B cells, not via CSR)", "Enzymes: AID (activation-induced cytidine deaminase), essential for both SHM and CSR", "Plasma cells: terminally differentiated, secrete antibody at ~2000 molecules/second, migrate to bone marrow for long-term survival", "Memory B cells: long-lived, rapid secondary response; subsets: IgM memory, IgG memory, atypical memory (malaria, HIV)", "B cell subsets: follicular (FO), marginal zone (MZ, rapid T-independent response), B-1 (natural antibodies, innate-like)", "Antigen presentation: B cells are professional APCs, internalize antigen via BCR, present on MHC II", "Cytokine production: IL-10 (regulatory B cells / Bregs), IL-6, TNF-α", "T-independent responses: rapid but lower affinity; basis for polysaccharide vaccines (pneumococcal)"], "clinical": "B cell deficiency (X-linked agammaglobulinemia, CVID) → recurrent infections. Dysregulated B cells → autoimmune disease (SLE, RA), allergies (IgE class switch), B cell lymphomas. Anti-CD20 (rituximab) depletes B cells in autoimmunity and lymphoma. Monoclonal antibodies are engineered B cell products.", "analogyBreak": "The \"weapons designer\" metaphor captures antibody production but misses B cells' roles as antigen presenters, cytokine producers, and immune regulators. Bregs actively suppress inflammation. They are not always pro-immune."}, {"id": "plasma", "name": "Plasma Cell", "tagline": "The antibody factory", "lineage": "lymphoid", "lineageLabel": "Lymphoid", "summary": "The mass-production arm of the B cell response. These cells sacrifice everything, mobility, surface receptors, even their own lifespan, to pump out antibodies at staggering rates.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><rect x=\"6\" y=\"6\" width=\"20\" height=\"20\" rx=\"3\"/><path d=\"M10 10h12M10 14h12M10 18h8M10 22h6\" stroke-linecap=\"round\"/><circle cx=\"24\" cy=\"22\" r=\"3\" fill=\"currentColor\" opacity=\"0.3\"/></svg>", "story": "When the B cell designs the weapon, the plasma cell is the factory that never sleeps. Picture a production line running 24/7, churning out millions of identical antibody missiles per hour. These cells are so dedicated to production that they strip away everything else, no more antigen receptors, no more mobility. Just endoplasmic reticulum, ribosomes, and a single purpose. Some factories run for weeks then close; others move to the bone marrow and run for decades.", "simpleRole": "Terminally differentiated B cell that secretes antibodies. Produces antibodies at an extraordinary rate (~2000 molecules/second). Short-lived (days to weeks) or long-lived (years to decades in bone marrow).", "advanced": ["Derived from B cells after germinal centre reaction (or extrafollicular response for early antibody)", "Morphology: large, eccentric nucleus, clock-face chromatin, prominent Golgi, massive rough ER", "Antibody production: ~2000 immunoglobulin molecules/second", "Transcription factors: BLIMP-1 (master regulator), XBP-1 (ER stress/secretion), IRF4", "Short-lived plasma cells: extrafollicular, days to weeks, first wave of antibody", "Long-lived plasma cells: bone marrow niches, survive for years to decades via BCMA, APRIL, IL-6 from stromal cells", "Survival factors: BAFF, APRIL (from stromal cells), IL-6", "Surface markers: CD138+, CD38+, CD20- (key distinction from B cells)", "Antibody specificity: fixed, cannot undergo further class switch or affinity maturation", "Bone marrow niche: stromal cells provide survival signals; this is why plasma cells persist long after the infection clears"], "clinical": "Long-lived plasma cells are the basis of vaccine immunity (decades of antibody protection). They are also the source of pathology in multiple myeloma (malignant plasma cell cancer) and antibody-mediated autoimmune diseases (SLE, myasthenia gravis). Plasma cells are resistant to anti-CD20 therapy (CD20-negative), a challenge for autoimmune disease treatment.", "analogyBreak": "The \"factory\" metaphor is apt but implies a static, unchanging product. In reality, the antibody repertoire shifts over time as old plasma cells die and new ones are generated. The bone marrow is more like a warehouse of different factories, each producing a different antibody."}, {"id": "cd4", "name": "CD4+ T Helper Cell", "tagline": "The strategic coordinator", "lineage": "lymphoid", "lineageLabel": "Lymphoid", "summary": "The general who never fires a weapon but directs the entire immune response. CD4+ T cells tell B cells to make antibodies, macrophages to fight harder, and CD8+ T cells to kill.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"16\" cy=\"10\" r=\"4\"/><path d=\"M8 26c0-4 4-8 8-8s8 4 8 8\" /><path d=\"M16 14v6M10 18l3 2M22 18l-3 2\" stroke-linecap=\"round\"/></svg>", "story": "Picture a military commander in a command centre. They don't fight on the front lines. They coordinate. They receive intelligence from dendritic cells, then dispatch orders: \"B cells, start producing antibodies!\" \"Macrophages, keep fighting!\" \"CD8+ T cells, eliminate those infected cells!\" Different commanders specialize in different threats, some fight viruses, others fight parasites, others fight bacteria. Without the coordinator, the immune system is an army without orders.", "simpleRole": "T lymphocyte that recognizes antigen presented on MHC II. Does not directly kill pathogens, instead coordinates the immune response by activating other cells through cytokines and cell contact. Master regulator of adaptive immunity.", "advanced": ["Development: thymus, from common lymphoid progenitor; positive and negative selection", "TCR: αβ heterodimer, recognizes peptide-MHC II complex", "Activation: requires Signal 1 (TCR + peptide-MHC II), Signal 2 (CD28 → CD80/86 co-stimulation), Signal 3 (polarizing cytokines)", "Subsets (polarization): Th1 (IFN-γ, TBX21, fights intracellular pathogens), Th2 (IL-4/5/13, GATA3, parasites/allergy), Th17 (IL-17, RORγt, extracellular bacteria/fungi), Tfh (Bcl6, CXCR5, helps B cells in germinal centres), Treg (FOXP3, suppression)", "Tfh cells: migrate to B cell follicles, provide CD40L + IL-21 to B cells in germinal centres, essential for affinity maturation and class switch", "Memory: central memory (TCM), effector memory (TEM), tissue-resident memory (TRM)", "Cytokine hierarchies: T-bet → IFN-γ → Th1; GATA3 → IL-4 → Th2; RORγt → IL-17 → Th17; FOXP3 → Treg", "Lineage plasticity: subsets can convert under cytokine influence (Th17 → Treg, Th1 → Tfh)", "T-cell exhaustion: chronic antigen exposure (cancer, chronic infection) → PD-1, LAG-3, TIM-3, reduced effector function", "Immunometabolism: Th1/Th17 = glycolytic; Treg = oxidative phosphorylation; Tfh = mitochondrial", "Superantigens: bypass normal processing, cross-link MHC II with TCR Vβ → massive cytokine release (toxic shock)"], "clinical": "HIV destroys CD4+ T cells → AIDS. Th17/Treg imbalance → autoimmune disease (IBD, MS, RA). Th2 excess → allergy and asthma. T-cell exhaustion → cancer immune evasion (checkpoint inhibitors target PD-1 to restore function). Th17 dysregulation → psoriasis, ankylosing spondylitis.", "analogyBreak": "The \"commander\" metaphor implies top-down control, but CD4+ T cells are also shaped by their environment. Dendritic cells, cytokines, and tissue context determine which subset they become. The commander doesn't choose the strategy alone, the battlefield shapes the decision."}, {"id": "cd8", "name": "CD8+ Cytotoxic T Cell", "tagline": "The precision strike team", "lineage": "lymphoid", "lineageLabel": "Lymphoid", "summary": "Elite killer lymphocytes that eliminate virus-infected and cancerous cells with surgical precision. Each one is trained to recognize a single specific target.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><path d=\"M16 4l3 8h8l-6 5 2 9-7-5-7 5 2-9-6-5h8z\" stroke-linejoin=\"round\"/></svg>", "story": "Picture an elite sniper team. Each soldier is trained for exactly one target, a specific viral protein or cancer mutation. They patrol the body, checking every cell's ID badge (MHC I). When they find a cell displaying their target, they strike with lethal precision: perforin punches holes in the target, granzymes enter and trigger apoptosis. Clean, efficient, no collateral damage. After the mission, some become memory cells, veterans who remember the enemy forever.", "simpleRole": "Cytotoxic T lymphocyte (CTL). Recognizes antigen presented on MHC I (present on nearly all cells). Kills virus-infected cells, tumour cells, and transplanted cells using perforin and granzymes. Essential for clearing intracellular infections.", "advanced": ["Development: thymus; positive selection on MHC I, negative selection removes self-reactive clones", "TCR: αβ, recognizes peptide-MHC I (8-10 amino acid peptides)", "Activation: requires Signal 1 (TCR + peptide-MHC I), Signal 2 (CD28 → CD80/86, typically from DCs), Signal 3 (IL-2 or type I IFN)", "Killing mechanisms: perforin (pore-forming), granzymes (serine proteases → caspase activation → apoptosis), FasL → Fas (death receptor)", "Cytokines: IFN-γ, TNF-α, anti-viral, activates macrophages", "Memory: central memory (TCM, lymph node patrol), effector memory (TEM, tissue patrol), tissue-resident memory (TRM, permanent tissue garrison)", "TRM cells: CD69+, CD103+, reside in skin, gut, lung, brain, first line of defence upon reinfection", "Exhaustion: PD-1, LAG-3, TIM-3, TIGIT upregulation; reduced cytokine production and killing; driven by chronic antigen exposure (cancer, HIV, HCV)", "Checkpoint blockade: anti-PD-1/PD-L1 reinvigorates exhausted CD8+ T cells, basis of modern cancer immunotherapy; anti-CTLA-4 primarily enhances priming and reduces Treg suppression", "Immunometabolism: naive = oxidative phosphorylation; effector = glycolytic; memory = fatty acid oxidation + spare respiratory capacity", "Cross-presentation: DCs present exogenous antigen on MHC I to prime CD8+ T cells, essential for anti-viral and anti-tumour responses"], "clinical": "CD8+ T cell deficiency → severe viral infections, cancer susceptibility. T-cell exhaustion is the major barrier in cancer immunotherapy, checkpoint inhibitors (anti-PD-1, anti-CTLA-4) restore T cell function. CAR-T cell therapy uses engineered T cells (containing both CD4+ and CD8+ T cells) for cancer treatment. TRM cells are targets for next-generation mucosal vaccines.", "analogyBreak": "The \"sniper\" metaphor captures specificity but not the broader roles of CD8+ T cells: they also produce cytokines (IFN-γ), help shape tissue immunity, and can even perform regulatory functions. They are not silent assassins. They actively communicate and remodel their environment."}, {"id": "treg", "name": "Regulatory T Cell (Treg)", "tagline": "Internal affairs", "lineage": "lymphoid", "lineageLabel": "Lymphoid", "summary": "The immune system's peacekeepers. Tregs suppress excessive immune responses, prevent autoimmunity, and call off the attack when the threat is gone.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><path d=\"M16 4l8 4v8c0 5-3.5 9-8 12-4.5-3-8-7-8-12V8l8-4z\"/><path d=\"M12 16l3 3 5-6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>", "story": "Every city needs internal affairs, officers who police the police. Tregs are the immune system's brake pedal. When the fight is won, they step in and say: \"Stand down. The threat is gone.\" They suppress overzealous immune cells, prevent friendly fire on the body's own tissues, and maintain peace. Without them, the immune system attacks everything, including you.", "simpleRole": "Specialized T cell (CD4+CD25+FOXP3+) that suppresses immune responses. Prevents autoimmunity, limits inflammation, and maintains immune tolerance. The immune system's essential brake.", "advanced": ["Master transcription factor: FOXP3, mutations cause IPEX syndrome (fatal autoimmunity)", "Two origins: thymic Tregs (tTreg, self-reactive, central tolerance) and peripheral Tregs (pTreg, induced from naive CD4+ T cells, peripheral tolerance)", "Surface markers: CD4+, CD25high, CD127low, FOXP3+", "Suppression mechanisms: IL-10 and TGF-β secretion, CTLA-4 (strips CD80/86 from APCs), IL-2 consumption (deprives effector T cells), adenosine generation (CD39/CD73)", "CTLA-4 mechanism: Tregs capture and degrade CD80/86 from APCs via transendocytosis, effectively removing co-stimulation", "Tissue-specific Tregs: have unique functions in different tissues (muscle repair, skin wound healing, fat metabolism)", "Plasticity: under inflammatory conditions, Tregs can lose FOXP3 and become effector cells (ex-Tregs), implicated in autoimmunity", "Tumour-infiltrating Tregs: suppress anti-tumour immunity, a major barrier to cancer immunotherapy", "Immunometabolism: rely on oxidative phosphorylation and fatty acid oxidation (unlike effector T cells which use glycolysis)", "Stability: epigenetic stability of the TSDR (Treg-specific demethylated region) of the FOXP3 locus determines lineage commitment"], "clinical": "Treg deficiency (IPEX syndrome) → severe autoimmunity. Treg dysfunction → type 1 diabetes, MS, RA, IBD. Treg therapy (expanding patient's Tregs ex vivo) is in clinical trials for transplantation and autoimmunity. Tumour Tregs are targets for cancer immunotherapy (anti-CCR4, anti-CD25 depletes Tregs in tumours).", "analogyBreak": "The \"internal affairs\" metaphor implies Tregs only police other cells. In reality, Tregs also actively remodel tissue environments, promote wound healing, and regulate metabolism. They are not just suppressors. They are tissue-specific regulators with diverse functions beyond immune suppression."}, {"id": "mast", "name": "Mast Cell", "tagline": "The fire alarm system", "lineage": "myeloid", "lineageLabel": "Myeloid", "summary": "Tissue-resident alarm cells that trigger immediate inflammatory responses. They are the city's fire alarms, sitting quietly until triggered, then unleashing chaos.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><path d=\"M16 6c-2 0-4 1-5 3-1 2-1 4 0 6 1 2 3 3 5 3s4-1 5-3c1-2 1-4 0-6-1-2-3-3-5-3z\"/><path d=\"M12 12l-4-4M20 12l4-4M10 16l-5 3M22 16l5 3M16 18v6\" stroke-linecap=\"round\"/></svg>", "story": "Imagine fire alarm boxes on every street corner, painted red, loaded with alarms, waiting. Mast cells sit in skin, gut, and airways, packed with granules full of histamine and other alarm chemicals. When they detect a trigger (allergen, injury, pathogen), they explode, releasing their contents in seconds. Blood vessels widen, fluid rushes in, nerves fire (itching, pain), and other immune cells are alerted. It is the fastest alarm in the body.", "simpleRole": "Tissue-resident cell packed with inflammatory granules. Releases histamine, proteases, and cytokines upon activation. Drives immediate allergic reactions (anaphylaxis), wound healing, and pathogen defence. The master of rapid inflammation.", "advanced": ["Development: bone marrow progenitor → matures in tissues (unique among immune cells)", "Location: skin, gut mucosa, airways, around blood vessels and nerves", "Granule contents: histamine, tryptase, chymase, heparin, proteoglycans, TNF-α (pre-formed)", "Activation: FcεRI cross-linking by IgE (allergy), complement (C3a, C5a), PAMPs, physical stimuli, neuropeptides", "Mediator release: immediate (minutes, histamine, proteases) and delayed (hours, PGD2, LTC4, cytokines: IL-4, IL-5, IL-13, TNF-α)", "Subsets: connective tissue mast cells (tryptase+, chymase+, TC mast cells) vs mucosal mast cells (tryptase+ only, T mast cells)", "IgE-mediated allergy: allergen → IgE binding → FcεRI cross-linking → degranulation → immediate allergic reaction", "Defense roles: anti-parasite (especially helminths), anti-bacterial (via cathelicidins, defensins), snake venom neutralisation", "Wound healing: release of VEGF, FGF, proteases → angiogenesis and tissue remodelling", "Neuroimmune interaction: mast cells communicate with sensory nerves via histamine and substance P, drives itch and pain", "Tolerogenic potential: can be immunosuppressive in certain contexts (IL-10 production)"], "clinical": "Mast cell activation → allergic rhinitis, asthma, anaphylaxis. Mastocytosis (excess mast cells) → skin lesions, systemic symptoms. Mast cell mediators drive chronic urticaria. Anti-IgE (omalizumab) and mast cell stabilizers are therapeutic targets. Emerging role in neuroinflammation and chronic pain.", "analogyBreak": "The \"fire alarm\" metaphor captures the speed of mast cell responses but underrepresents their sophisticated roles in tissue remodelling, host defence, and neuroimmune communication. They are not just alarms. They are active participants in tissue homeostasis and wound healing."}, {"id": "eosinophil", "name": "Eosinophil", "tagline": "The heavy artillery", "lineage": "myeloid", "lineageLabel": "Myeloid", "summary": "Specialized granulocyte designed to fight parasites that are too large to phagocytose. They release toxic chemicals directly onto the target, like artillery firing at a fortress.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"16\" cy=\"16\" r=\"10\"/><circle cx=\"13\" cy=\"14\" r=\"2\" fill=\"currentColor\"/><circle cx=\"19\" cy=\"14\" r=\"2\" fill=\"currentColor\"/><path d=\"M12 20h8\" stroke-linecap=\"round\"/></svg>", "story": "Some enemies are too big to eat. When a parasitic worm, a creature larger than the eosinophil itself, invades the body, the eosinophil uses a different strategy. It positions itself next to the parasite and unleashes a barrage of toxic chemicals: major basic protein, eosinophil peroxidase, eosinophil cationic protein. It is like artillery firing at a fortress, you cannot swallow it, so you bombard it until it dies.", "simpleRole": "Granulocyte specialized for anti-parasite defence. Releases toxic granule proteins directly onto large pathogens (helminths) that cannot be phagocytosed. Also involved in allergic inflammation, especially asthma.", "advanced": ["Development: bone marrow, myeloid lineage; IL-5 is the key cytokine for production and survival", "Granule proteins: major basic protein (MBP), eosinophil cationic protein (ECP), eosinophil peroxidase (EPO), eosinophil-derived neurotoxin (EDN)", "Degranulation: exocytosis of granule contents onto the target surface; also piecemeal degranulation and cytolysis (release of intact granules)", "Receptors: IL-5R (survival), Fc receptors (IgA, IgG), complement receptors, PRRs", "Cytokine production: IL-4, IL-5, IL-13 (amplify Th2 response), IL-10, TGF-β", "Lipid mediators: leukotrienes (LTC4), prostaglandins, PAF", "Extracellular traps: eosinophil ETs (EETs), DNA decorated with granule proteins", "Tissue remodelling: collagen deposition, fibrosis (chronic eosinophilic inflammation)", "Immunoregulation: can suppress T cell proliferation (IDO, TGF-β)", "Two faces: protective (anti-parasite) and pathological (allergy, asthma, tissue damage)", "Life cycle: short in blood (~8-12 hours), longer in tissues (days to weeks)"], "clinical": "Eosinophilia → parasitic infection, allergic disease (asthma, eczema, eosinophilic oesophagitis), hypereosinophilic syndrome, drug reactions. Anti-IL-5 (mepolizumab, reslizumab) and anti-IL-5Rα (benralizumab) are transformative for severe eosinophilic asthma. Eosinophilic oesophagitis is an emerging disease with increasing prevalence.", "analogyBreak": "The \"artillery\" metaphor captures the destructive power but not the regulatory and reparative roles of eosinophils. They also produce immunoregulatory cytokines, promote tissue remodelling, and can even have anti-inflammatory functions. They are not purely destructive. They are dual-natured."}, {"id": "basophil", "name": "Basophil", "tagline": "The backup alarm", "lineage": "myeloid", "lineageLabel": "Myeloid", "summary": "The rarest granulocyte. Circulating alarm cell that amplifies allergic and anti-parasite responses. Like mast cells, but mobile. They rush to tissues when needed.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"16\" cy=\"16\" r=\"10\"/><circle cx=\"12\" cy=\"13\" r=\"1.5\" fill=\"currentColor\" opacity=\"0.4\"/><circle cx=\"20\" cy=\"13\" r=\"1.5\" fill=\"currentColor\" opacity=\"0.4\"/><circle cx=\"16\" cy=\"19\" r=\"1.5\" fill=\"currentColor\" opacity=\"0.4\"/><circle cx=\"12\" cy=\"20\" r=\"1.5\" fill=\"currentColor\" opacity=\"0.4\"/><circle cx=\"20\" cy=\"20\" r=\"1.5\" fill=\"currentColor\" opacity=\"0.4\"/></svg>", "story": "Basophils are the mobile backup to the mast cells' stationary alarm system. They patrol the bloodstream, the least common of the granulocytes, but when called to action, they rush to tissues and release histamine and other mediators. They also serve as APCs for Th2 responses, presenting allergens to T cells and amplifying the allergic cascade.", "simpleRole": "Circulating granulocyte (rarest, <1% of white blood cells) that mediates allergic reactions and anti-parasite immunity. Releases histamine and Th2-promoting cytokines. Can present antigen to T cells.", "advanced": ["Development: bone marrow, myeloid lineage; distinct from mast cells despite shared features", "Granule contents: histamine, proteases, heparin, rapid IL-4 production (not pre-formed in all species/contexts)", "Activation: FcεRI cross-linking (IgE), complement (C3a, C5a), cytokines (IL-3, IL-18)", "Cytokine production: IL-4, IL-13 (Th2 polarization), basophils are a major early source of rapid IL-4 production", "Antigen presentation: can express MHC II and promote Th2 responses in some contexts, not a canonical APC role like DCs", "Role in allergy: amplify IgE-mediated reactions; contribute to chronic allergic inflammation", "Anti-parasite: recruited to sites of helminth infection; release toxic mediators", "Distinction from mast cells: basophils are circulating, shorter-lived, different granule protease content, developmentally distinct", "Markers: CD123+ (IL-3R), FcεRI+, CD203c+ (activation marker)", "Immunoregulation: can promote tolerance in certain contexts via IL-4 and TGF-β"], "clinical": "Basophilia → chronic myeloid leukaemia (CML), myelofibrosis, allergic disease. Basophil activation markers (CD203c) used in allergy diagnostics. Basophils are emerging therapeutic targets in allergic disease and as biomarkers for CML treatment response.", "analogyBreak": "The \"backup alarm\" metaphor suggests a secondary role, but basophils have unique functions: they are major early producers of IL-4 (shaping Th2 responses) and can act as APCs, roles mast cells cannot fully replicate. They are not redundant. They are complementary."}, {"id": "monocyte", "name": "Monocyte", "tagline": "The mobile reserve force", "lineage": "myeloid", "lineageLabel": "Myeloid", "summary": "Circulating precursor cells that rush to sites of inflammation and transform into macrophages or dendritic cells. They are the city's deployable workforce.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"16\" cy=\"16\" r=\"9\"/><path d=\"M10 16c0-3 3-6 6-6M16 10c3 0 6 3 6 6\" stroke-linecap=\"round\" opacity=\"0.5\"/><circle cx=\"14\" cy=\"15\" r=\"1.5\" fill=\"currentColor\"/><circle cx=\"18\" cy=\"18\" r=\"1.5\" fill=\"currentColor\"/></svg>", "story": "Monocytes are the reserves waiting in the bloodstream, the National Guard of the immune system. When inflammation calls, they rush to the tissue, cross the border (endothelium), and transform. Some become macrophages (street cleaners), others become dendritic cells (intelligence officers), and others become inflammatory macrophages that fight the fire. What they become depends on the signals they receive at the site.", "simpleRole": "Circulating blood cell that differentiates into macrophages or dendritic cells upon entering tissues. Bridge between bone marrow production and tissue immune response. Key player in inflammation and tissue repair.", "advanced": ["Development: bone marrow, from granulocyte-monocyte progenitor (GMP); regulated by M-CSF and GM-CSF", "Subsets (human): classical (CD14++CD16-, inflammatory), intermediate (CD14++CD16+), non-classical (CD14+CD16++, patrolling)", "Patrolling monocytes: crawl along vascular endothelium, survey for damage, first responders to vascular injury", "Tissue entry: follow chemokine gradients (CCL2, CCL7, CCL8 → CCR2; CX3CL1 → CX3CR1)", "Differentiation fate: inflammatory macrophages (GM-CSF), tissue-resident macrophage replacement (M-CSF), dendritic cells (GM-CSF + IL-4)", "Inflammatory monocytes: produce TNF-α, IL-1, iNOS; essential for clearing bacterial and fungal infections", "Resolution phase monocytes: can switch to pro-repair phenotype (Ly6C-low in mice)", "Emergency monopoiesis: during severe infection, bone marrow accelerates monocyte production", "Heterogeneity: transcriptionally distinct from tissue-resident macrophages; do not fully replace resident populations", "Cardiovascular disease: monocyte-derived macrophages drive atherosclerotic plaque formation", "Cancer: tumour-associated macrophages (TAMs) often derive from recruited monocytes"], "clinical": "Monocytosis → chronic infections (TB), autoimmune disease, myeloid malignancies (CMML). Classical monocytes are biomarkers for cardiovascular risk. Monocyte-derived macrophages drive atherosclerosis and tumour progression. Therapeutic targeting of monocyte recruitment (anti-CCR2) is in clinical development.", "analogyBreak": "The \"reserve force\" metaphor implies monocytes are undifferentiated blanks. In reality, monocyte subsets are already pre-programmed with distinct functions before they enter tissues. They are not blank slates. They carry information from their origin and circulation experience."}, {"id": "ilc", "name": "Innate Lymphoid Cell (ILC)", "tagline": "The neighborhood watch", "lineage": "innate", "lineageLabel": "Innate Lymphoid", "summary": "Innate counterparts of T helper cells. They respond within hours to tissue damage, without needing antigen-specific recognition. The local first responders of the lymphoid world.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"16\" cy=\"16\" r=\"10\"/><path d=\"M16 8v16M8 16h16\" stroke-linecap=\"round\" opacity=\"0.3\"/><circle cx=\"16\" cy=\"16\" r=\"4\"/><path d=\"M12 12l-3-3M20 12l3-3M12 20l-3 3M20 20l3 3\" stroke-linecap=\"round\" opacity=\"0.5\"/></svg>", "story": "ILCs are the neighborhood watch. They live in the tissues, not the barracks (lymph nodes). Unlike T cells, they do not need to be briefed on a specific enemy. They sense tissue damage and cytokine alarms, then respond within hours: ILC1s fight viruses (like Th1 cells), ILC2s fight parasites and drive allergy (like Th2 cells), ILC3s defend mucosal barriers (like Th17 cells). They are the innate mirrors of the adaptive T helper subsets.", "simpleRole": "Innate lymphocytes (no antigen-specific receptor) that mirror T helper cell functions. Respond rapidly to cytokine signals from damaged tissue. Three main groups: ILC1 (IFN-γ, anti-viral), ILC2 (IL-5/IL-13, anti-parasite/allergy), ILC3 (IL-17/IL-22, mucosal defence).", "advanced": ["Development: common lymphoid progenitor → helper ILCs are IL-7-dependent (NK cells are IL-15-dependent); Notch signalling is subset/context-dependent; Id2 and PLZF are key transcription factors for important helper ILC progenitors (not all ILC lineages)", "No rearranged antigen receptor (no RAG recombination), innate-like, not antigen-specific", "Group 1 (ILC1): T-bet+, produce IFN-γ, respond to IL-12 and IL-18; anti-viral and intracellular pathogen defence", "Group 2 (ILC2): GATA3+, produce IL-5, IL-9, IL-13; respond to IL-25, IL-33, TSLP (alarmins from epithelial cells); anti-helminth, allergy, asthma, tissue repair", "Group 3 (ILC3): RORγt+, produce IL-17A, IL-22; respond to IL-23; mucosal defence, barrier integrity, anti-fungal/bacterial; enriched in gut", "Natural killer cells are cytotoxic group 1 ILCs, distinct from helper-like ILC1s", "LTi (lymphoid tissue inducer) cells: ILC3 subset essential for lymph node and Peyer's patch development during embryogenesis", "Tissue residency: ILCs are largely tissue-resident; do not recirculate like T cells", "Plasticity: ILC subsets can convert under cytokine influence (ILC3 → ILC1, ILC2 → ILC1)", "Amphiregulin: ILC2s produce amphiregulin for tissue repair independent of inflammation", "Neuroimmune: ILC2s respond to neuromedin U (from neurons); ILC3s respond to vasoactive intestinal peptide (VIP)"], "clinical": "ILC2 dysfunction → asthma, allergic rhinitis, atopic dermatitis. ILC3 dysfunction → IBD, barrier failure. ILCs contribute to tissue repair and fibrosis. ILCs are emerging targets for mucosal vaccine design and biologics (anti-TSLP for asthma targets ILC2 pathways).", "analogyBreak": "The \"neighborhood watch\" metaphor captures the local, rapid nature of ILCs but underrepresents their sophistication. ILCs communicate with neurons (neuroimmune axis), contribute to tissue development (lymph organogenesis), and have memory-like states. They are not just watchers. They are tissue architects."}, {"id": "memory", "name": "Memory T & B Cells", "tagline": "The veterans & archivists", "lineage": "lymphoid", "lineageLabel": "Lymphoid", "summary": "Long-lived cells that remember past encounters. They are the immune system's archive, ensuring the next response to a known threat is faster, stronger, and more precise.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><path d=\"M16 4v24M4 16h24\" opacity=\"0.2\"/><circle cx=\"16\" cy=\"16\" r=\"6\"/><path d=\"M16 10v-3M16 22v3M10 16h-3M22 16h3\" stroke-linecap=\"round\"/><circle cx=\"16\" cy=\"16\" r=\"2\" fill=\"currentColor\" opacity=\"0.5\"/></svg>", "story": "After every battle, some soldiers do not return to civilian life. They become veterans, cells that remember the enemy's face. When the same pathogen returns years later, these memory cells respond in hours instead of weeks, with 10-100x more force. This is why vaccines work: they train the veterans without the real war. Memory T cells patrol the blood and tissues; memory B cells wait in lymph nodes with antibody blueprints ready.", "simpleRole": "Long-lived lymphocytes generated after an immune response. On re-encountering the same antigen, they mount a faster, stronger, and more effective response than the original. The biological basis of vaccination and immunological memory.", "advanced": ["T memory subsets: TCM (central memory, CCR7+, CD62L+, lymph node patrol), TEM (effector memory, CCR7-, tissue patrol), TRM (tissue-resident, CD69+, CD103+, permanent garrison), TSCM (stem cell memory, self-renewing)", "B memory subsets: IgM memory (broad reactivity), IgG memory (high affinity, class-switched), atypical memory (malaria, HIV, exhausted phenotype)", "Generation: germinal centre reaction (B cells) or effector-to-memory transition (T cells); requires antigen clearance", "Memory inflation: some viruses (CMV) cause progressive accumulation of memory T cells over time", "TRM cells: tissue-resident, do not recirculate; first line of defence at barrier tissues; can provide cross-protection", "Affinity maturation in memory B cells: secondary response antibodies have higher affinity due to ongoing somatic hypermutation", "Longevity: memory cells can persist for decades (measles, 65+ years; smallpox, 75+ years)", "Heterologous immunity: memory T cells cross-react with unrelated pathogens, can be protective or pathogenic", "Immunometabolism: memory T cells have enhanced spare respiratory capacity (SRC) via fatty acid oxidation; enables rapid recall", "Epigenetic programming: memory cells retain chromatin accessibility at effector gene loci, basis for rapid secondary response", "Bystander activation: memory cells can be activated by cytokines without antigen-specific recognition, relevant in autoimmunity", "Original antigenic sin (immune imprinting): memory B cells from a prior infection can dominate the response to a new but related strain (e.g., influenza), now termed \"immune imprinting\""], "clinical": "Memory cells are the basis of all vaccination. T-cell exhaustion can erode memory (HIV, cancer). TRM cells are targets for next-generation mucosal vaccines. Heterologous immunity explains some vaccine cross-protection and adverse events. Original antigenic sin complicates influenza vaccine design.", "analogyBreak": "The \"veteran\" metaphor captures memory but implies a static record. Memory cells are dynamic. They undergo homeostatic proliferation, can be re-educated by new encounters, and sometimes lose function (exhaustion). Memory is not a photograph. It is a living, evolving record that can fade, strengthen, or even mislead."}, {"id": "complement", "name": "Complement System", "tagline": "The city's alarm network", "lineage": "bridge", "lineageLabel": "Bridge", "summary": "Not a cell but a system of proteins that cascade like falling dominoes. It tags pathogens for destruction, punches holes in their membranes, and amplifies inflammation, the city's automated defence network.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"8\" cy=\"8\" r=\"3\"/><circle cx=\"24\" cy=\"8\" r=\"3\"/><circle cx=\"16\" cy=\"16\" r=\"3\"/><circle cx=\"8\" cy=\"24\" r=\"3\"/><circle cx=\"24\" cy=\"24\" r=\"3\"/><path d=\"M10.5 10.5l3 3M21.5 10.5l-3 3M10.5 21.5l3-3M21.5 21.5l-3-3\" stroke-linecap=\"round\" opacity=\"0.5\"/></svg>", "story": "The complement system is not a cell. It is the city's automated alarm and defence network. Imagine a series of sensors throughout the city: when one detects an intruder, it triggers a chain reaction. Proteins activate each other in sequence (like dominoes), amplifying the signal a thousandfold. They paint targets on pathogens (opsonization, \"tag for destruction\"), punch holes in microbial membranes (MAC, membrane attack complex), and send alarm signals (anaphylatoxins) that recruit immune cells. It is fast, ancient, and deadly.", "simpleRole": "System of ~30 plasma proteins that cascade-activate upon pathogen encounter. Three functions: opsonization (tag pathogens for phagocytosis), lysis (punch holes in membranes via MAC), and inflammation (anaphylatoxins C3a, C5a recruit immune cells).", "advanced": ["Three activation pathways: classical (antibody-antigen complex), alternative (spontaneous hydrolysis, microbial surfaces), lectin (mannose-binding lectin recognizes microbial sugars)", "All converge on C3 convertase → C3b (opsonization) → C5 convertase → C5b-9 (MAC, membrane attack complex)", "C3b opsonization: tagged pathogens are recognized by complement receptors (CR1, CR3) on phagocytes", "Anaphylatoxins: C3a, C5a, recruit neutrophils and monocytes, activate mast cells, increase vascular permeability", "C5a: potent chemoattractant; also activates neutrophils and enhances phagocytosis", "Regulation: Factor H, Factor I, C1-inhibitor, CD55 (DAF), CD59, C4bp, prevent damage to host cells", "Classical pathway: C1q binds IgM or IgG-antigen complex, links innate and adaptive immunity", "Lectin pathway: MBL, ficolins recognize pathogen-associated carbohydrate patterns", "Alternative pathway: amplification loop, continuously ticks over on microbial surfaces", "Crosstalk: complement enhances B cell responses (CR2/CD21 is a B cell co-receptor); modulates T cell responses", "Complement and coagulation: interconnected cascades; complement activates coagulation and vice versa", "Intracellular complement: recent discovery of intracellular C3 activation and autocrine signalling (\"complosome\")"], "clinical": "Complement deficiency: terminal pathway deficiency → recurrent Neisseria infections; early classical pathway deficiency (C1q, C1r/s, C2, C4) → SLE and immune-complex disease. C1-inhibitor deficiency → hereditary angioedema. Complement overactivation → atypical HUS, C3 glomerulopathy. Anti-C5 (eculizumab) treats PNH and atypical HUS. Complement contributes to AMD, transplant rejection, and ischemia-reperfusion injury.", "analogyBreak": "The \"alarm network\" metaphor captures the cascade amplification but misses complement's roles in development, synaptic pruning (brain), tissue regeneration, and intracellular signalling. The \"complosome\" concept shows complement is not just a plasma cascade. It operates inside cells as a metabolic and signalling regulator."}, {"id": "gdt", "name": "γδ T Cell", "tagline": "The border patrol", "lineage": "lymphoid", "lineageLabel": "Lymphoid", "summary": "Unconventional T cells that patrol barrier tissues (skin, gut, lung) and respond to stress signals without needing MHC-restricted antigen presentation. They are the border patrol, first to react at the body's frontiers.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><path d=\"M4 16h6M22 16h6\" stroke-linecap=\"round\"/><circle cx=\"16\" cy=\"16\" r=\"6\"/><path d=\"M13 13l3 3M16 10v6\" stroke-linecap=\"round\" opacity=\"0.5\"/></svg>", "story": "Picture border patrol officers stationed at the city gates, skin, gut, lungs. Unlike regular police (αβ T cells), they don't wait for a warrant (MHC-restricted antigen). They respond to general distress signals: stress markers, phosphoantigens from bacteria, changes in cell surface molecules. When they see trouble, they act immediately, killing infected cells, releasing cytokines, and calling for backup. They are the rapid reaction force at the body's frontiers.", "simpleRole": "Unconventional T cell with a γδ TCR (instead of αβ). Largely tissue-resident at barrier sites (skin, gut, lung). Responds to stress signals and phosphoantigens without MHC restriction. Bridges innate and adaptive immunity, rapid effector functions with some antigen specificity.", "advanced": ["TCR: γδ heterodimer, distinct from conventional αβ TCR; limited V-region diversity (oligoclonal, not random)", "Subsets by Vγ chain usage: Vγ9Vδ2 (circulating, anti-microbial/bacterial phosphoantigens), Vδ1 (tissue-resident, anti-stress), Vδ2 (innate-like)", "Antigen recognition: not MHC-restricted; recognizes phosphoantigens (IPP, HMBPP via butyrophilin BTN3A1), stress ligands (MICA/B, ULBP), lipids (via CD1), and undefined tumour antigens", "Effector functions: cytotoxicity (perforin/granzyme), cytokine production (IFN-γ, TNF-α, IL-17), antigen presentation to αβ T cells (some γδ subsets express MHC II)", "Vγ9Vδ2 T cells: major circulating subset; activated by microbial (E)PP metabolites via BTN3A1, unique to primates", "Tissue-resident γδ T cells: Vδ1+ subset enriched in skin and gut; can produce IL-17 (Th17-like) or IFN-γ (Th1-like) depending on tissue context", "Development: thymic origin; undergo selection and programming for effector fate before peripheral deployment (unlike αβ T cells which are largely naive when released)", "Plasticity: γδ T cells can adopt Th1, Th17, or Treg-like phenotypes depending on cytokine milieu", "Anti-tumour: γδ T cells can recognize and kill tumour cells; γδ T cell infiltration correlates with favorable prognosis in many cancers", "Trained immunity: γδ T cells exhibit memory-like responses after microbial stimulation (especially Vγ9Vδ2 after BCG vaccination)", "Adjuvant potential: γδ T cell agonists (phosphoantigens, anti-BTN3A1) are being explored as cancer immunotherapy"], "clinical": "γδ T cell deficiency → impaired barrier immunity, especially skin and mucosal infections. γδ T cells contribute to anti-tumour immunity, infiltration correlates with better prognosis in breast, colorectal, and other cancers. Vγ9Vδ2 agonists (zoledronate + IL-2, phosphoantigen-based) are in clinical trials for cancer immunotherapy. Dysregulated γδ T cells contribute to psoriasis (IL-17-producing subset).", "analogyBreak": "The \"border patrol\" metaphor captures the barrier location and rapid response but underrepresents the diversity of γδ subsets. Some γδ T cells circulate (not tissue-resident), some perform antigen presentation, and their antigen recognition is fundamentally different from αβ T cells. They are not simply \"faster T cells\" but a parallel lineage with unique biology."}, {"id": "mait", "name": "MAIT Cell", "tagline": "The microbial sensor", "lineage": "lymphoid", "lineageLabel": "Lymphoid", "summary": "Semi-invariant T cells that detect microbial vitamin B metabolites presented by MR1. They are the body's microbial sensor, bridging innate and adaptive immunity at mucosal barriers.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"16\" cy=\"16\" r=\"10\"/><path d=\"M10 10l6 6M16 16l6 6\" stroke-linecap=\"round\" opacity=\"0.4\"/><circle cx=\"16\" cy=\"16\" r=\"3\" fill=\"currentColor\" opacity=\"0.3\"/></svg>", "story": "Imagine a customs officer with a special scanner that detects microbial signatures, not the microbes themselves, but the chemical byproducts of bacterial metabolism. MAIT cells scan for microbial vitamin B9 (folate) derivatives that bacteria and yeast produce but humans don't. When they detect these metabolites, they respond within hours: killing infected cells, releasing cytokines, and recruiting other immune cells. They are abundant in blood and mucosal tissues, the microbial watchdogs of the body.", "simpleRole": "Semi-invariant T cell (invariant α-chain: TRAV1-2) that recognizes microbial vitamin B metabolites presented by MR1 (MHC class I-related protein 1). Abundant in blood (up to 10% of T cells) and mucosal tissues. Rapid innate-like responder to bacterial and fungal infections.", "advanced": ["TCR: semi-invariant, TRAV1-2 α-chain paired with limited β-chain diversity (TRBV6 or TRBV20); recognizes MR1-restricted microbial antigens", "Antigen: microbial riboflavin (vitamin B2) metabolites (5-OP-RU, 5-A-RU) presented by MR1, produced by most bacteria and yeast but not by mammalian cells", "MR1: MHC class I-related protein 1; monomorphic (not polymorphic like MHC I); conserved across mammals", "Activation: TCR + MR1-antigen (Signal 1), co-stimulation (Signal 2), cytokine signals (IL-12, IL-18, type I IFN for Signal 3)", "Effector functions: cytotoxicity (perforin/granzyme), cytokines (IFN-γ, TNF-α, IL-17), tissue repair (amphiregulin)", "Tissue distribution: blood (5-10% of T cells), liver (up to 50% of T cells in some individuals), gut lamina propria, lung, skin", "Development: thymic selection on MR1; MAIT cells acquire effector function during thymic development (innate-like, pre-programmed)", "Memory-like subsets: naive, memory, and effector MAIT cells distinguished by CD45RA/CD45RO and CD8 expression", "Microbial specificity: recognizes metabolites from riboflavin biosynthesis pathway, bacteria lacking this pathway (e.g., Enterococcus) are poorly recognized", "Immune regulation: MAIT cells can produce IL-17 (Th17-like) or IFN-γ (Th1-like) depending on cytokine milieu and tissue context", "Cancer: MAIT cells are found in tumours; role is context-dependent, can be anti-tumour (cytotoxic) or pro-tumour (immunosuppressive, IL-13 production)"], "clinical": "MAIT cell deficiency or dysfunction → impaired mucosal immunity, especially to bacterial and fungal infections. MAIT cells are depleted in HIV infection. MAIT cells contribute to autoimmune disease (IBD, MS) and metabolic disease (obesity, type 2 diabetes). Anti-MR1 antibodies and MR1 tetramers are tools for MAIT cell research and potential therapy. Tumour-infiltrating MAIT cells are being studied as immunotherapy targets.", "analogyBreak": "The \"microbial sensor\" metaphor captures the metabolite detection but overstates simplicity. MAIT cells also respond to cytokine-only stimulation (bystander activation), have tissue-specific functions (liver vs gut vs blood), and their role in cancer is dual-natured. They are not simple bacterial detectors. They are context-dependent immune regulators."}, {"id": "nkt", "name": "NKT Cell", "tagline": "The lipid detective", "lineage": "innate", "lineageLabel": "Innate Lymphoid", "summary": "T cells that recognize lipid antigens presented by CD1d. They bridge innate and adaptive immunity by responding to lipid signals from microbes and self-tissues within hours.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"16\" cy=\"16\" r=\"10\"/><path d=\"M16 6v20M6 16h20\" opacity=\"0.2\"/><path d=\"M10 10l6 6-6 6M22 10l-6 6 6 6\" stroke-linecap=\"round\" opacity=\"0.4\"/></svg>", "story": "Picture a detective who doesn't look for protein fingerprints like regular T cells, instead, they specialize in lipid evidence. NKT cells scan for lipid molecules presented by a special molecule (CD1d) rather than MHC. When they find microbial lipids or self-lipids altered by stress, they respond instantly: releasing massive amounts of cytokines that activate NK cells, macrophages, and dendritic cells. They are the immune system's rapid lipid-response team.", "simpleRole": "T cell with a semi-invariant TCR (Vα24Jα18 in humans) that recognizes lipid antigens presented by CD1d (non-classical MHC I-like molecule). Innate-like rapid responder. Activates downstream innate and adaptive immunity via cytokine bursts.", "advanced": ["TCR: Vα24Jα18 (human) / Vα14Jα18 (mouse), semi-invariant α-chain paired with limited β-chain diversity", "Antigen presentation: CD1d (non-polymorphic, MHC class I-like) presents lipid antigens, not peptides", "Lipid antigens: α-galactosylceramide (α-GalCer, prototypical agonist), microbial glycosphingolipids, self-lipids (lysophosphatidylcholine, phosphatidylinositol)", "Subsets: type I (invariant, Vα24Jα18+, α-GalCer reactive) and type II (diverse TCR, CD1d-restricted but not α-GalCer reactive)", "Effector functions: rapid cytokine production (IFN-γ, TNF-α, IL-4, IL-13, IL-17, IL-10) within hours of activation, can produce both Th1 and Th2 cytokines", "Downstream activation: NKT cells activate NK cells (via IFN-γ), dendritic cells (via CD40L), macrophages, and B cells, acting as immune amplifiers", "Development: thymic selection on CD1d; positive selection by double-positive thymocytes (not epithelial cells, unlike conventional T cells)", "Tissue distribution: liver (abundant), spleen, bone marrow, blood (low frequency, ~0.01-1% of T cells)", "Self-lipid recognition: type II NKT cells can recognize self-lipids, implications for autoimmunity and tolerance", "Tumour immunity: NKT cells can enhance anti-tumour responses via IFN-γ and activation of NK cells and DCs; α-GalCer is being tested as an anti-cancer adjuvant", "Microbial defence: NKT cells respond to lipid antigens from Sphingomonas, Ehrlichia, and other bacteria expressing glycosphingolipids"], "clinical": "NKT cell deficiency → impaired anti-tumour and anti-microbial immunity. NKT cell dysfunction implicated in autoimmune disease (type 1 diabetes, MS, systemic lupus). α-GalCer-based immunotherapy is in clinical trials for cancer. Type II NKT cells can suppress anti-tumour immunity, a target for checkpoint-like therapy. NKT cells contribute to atherosclerosis and metabolic disease.", "analogyBreak": "The \"lipid detective\" metaphor captures the lipid antigen recognition but understates the diversity of NKT subsets. Type I and type II NKT cells have opposing functions (pro- and anti-inflammatory), and NKT cells are major cytokine amplifiers rather than direct killers. They are not just lipid specialists. They are immune system conductors that shape the entire response."}, {"id": "mdsc", "name": "Myeloid-Derived Suppressor Cell", "tagline": "The corrupted officials", "lineage": "myeloid", "lineageLabel": "Myeloid", "summary": "Immature myeloid cells that suppress immune responses. In cancer, they are recruited by tumours to shut down anti-tumour immunity, the city's officials bribed to look the other way.", "icon": "<svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"16\" cy=\"16\" r=\"10\"/><path d=\"M10 14h12M10 18h8\" stroke-linecap=\"round\" opacity=\"0.4\"/><circle cx=\"16\" cy=\"16\" r=\"4\" stroke-dasharray=\"2 2\"/></svg>", "story": "Picture city officials who are supposed to protect citizens but have been bribed by a criminal organization (the tumour). MDSCs are immature myeloid cells that should mature into neutrophils, macrophages, or dendritic cells. But in cancer, the tumour releases signals that trap them in an immature state and reprograms them to suppress the immune system. They block T cell activation, deplete amino acids T cells need, and create a toxic environment that paralyzes anti-tumour immunity. They are the tumour's moles inside the immune system.", "simpleRole": "Heterogeneous population of immature myeloid cells that suppress T cell and NK cell responses. Pathologically expanded in cancer, chronic infection, and inflammation. Major barrier to anti-tumour immunity and cancer immunotherapy.", "advanced": ["Origin: bone marrow myeloid progenitors; expansion driven by tumour-derived GM-CSF, G-CSF, M-CSF, VEGF, IL-6, IL-1β", "Subsets: polymorphonuclear MDSCs (PMN-MDSC, granulocytic, CD11b+Ly6G+ in mice / CD11b+CD14-CD15+ in humans) and monocytic MDSCs (M-MDSC, CD11b+Ly6C+ in mice / CD11b+CD14+CD15- in humans)", "Suppression mechanisms: arginase-1 (depletes L-arginine), iNOS (produces NO), ROS/RNS (oxidative stress), IDO (depletes tryptophan), production of IL-10 and TGF-β", "Metabolic suppression: arginase-1 depletes L-arginine → T cells cannot express CD3ζ chain → T cell anergy; IDO depletes tryptophan → T cell apoptosis via GCN2 kinase", "T cell suppression: direct contact (PD-L1 expression), indirect (cytokine-mediated, metabolic competition)", "NK cell suppression: MDSCs downregulate NK cell activating receptors (NKG2D) via TGF-β and membrane-bound TGF-β", "Recruitment: tumour-derived chemokines (CCL2, CXCL8/IL-8, CXCL12) recruit MDSCs to tumour microenvironment", "Transdifferentiation: M-MDSCs can differentiate into tumour-associated macrophages (TAMs) within the tumour microenvironment", "Immunometabolism: MDSCs rely on glycolysis and fatty acid oxidation; HIF-1α drives immunosuppressive programming in hypoxic tumour environments", "Epigenetic programming: tumour-derived signals cause epigenetic changes (histone modifications, DNA methylation) that lock MDSCs in immunosuppressive state", "Therapeutic targeting: strategies include depletion (anti-Gr1, anti-Ly6G), differentiation (all-trans retinoic acid, ATRA), and functional inhibition (arginase inhibitors, ROS scavengers, anti-PD-L1)"], "clinical": "MDSCs are a major barrier to cancer immunotherapy. They suppress T cell and NK cell anti-tumour responses. MDSC accumulation correlates with poor prognosis in many cancers. Therapeutic strategies in clinical trials: ATRA (differentiation), arginase inhibitors (CB-1158), CSF1R inhibitors (M-MDSC depletion), and combination with checkpoint inhibitors. MDSCs also contribute to chronic infection (HIV, TB) and autoimmune disease (paradoxically protective in some autoimmune settings).", "analogyBreak": "The \"corrupted officials\" metaphor captures the tumour-protective role but overstates intentionality. MDSCs are not malevolent cells. They are normal myeloid precursors trapped in an immature state by pathological signals. In non-cancer settings (acute infection, wound healing), similar cells have protective roles. They are not inherently corrupt. They are context-dependent cells that the tumour microenvironment has co-opted."}], "cellKG": {"neutrophil": ["C001"], "macrophage": ["C003"], "dendritic": ["C004", "C005"], "nk": ["C006"], "bcell": ["C017", "C019"], "plasma": ["C018"], "cd4": ["C010", "C011", "C012", "C013", "C016"], "cd8": ["C015", "C027"], "treg": ["C014"], "mast": ["C007"], "eosinophil": ["C008"], "basophil": ["C021"], "monocyte": ["C002"], "ilc": ["C009"], "memory": ["C026", "C019"], "complement": ["P013", "M023", "M028"], "gdt": ["C022"], "mait": ["C023"], "nkt": ["C024"], "mdsc": ["C025"]}, "tcrSteps": [{"id": "s1", "type": "receptor", "name": "Antigen–MHC", "phase": "recognition", "desc": "Peptide presented on MHC engages the TCR", "function": "The initiating event: a peptide-MHC complex on an APC engages the TCR αβ heterodimer. The strength and duration of this interaction determines T-cell fate.", "upstream": "Antigen processing and presentation by APCs (dendritic cells, macrophages, B cells)", "downstream": ["TCR/CD3", "CD4/CD8 co-receptor"], "ifAbsent": "No antigen recognition occurs. T cells remain quiescent. No adaptive response is initiated.", "clinical": "MHC mismatch in transplantation triggers T-cell alloreactivity. Insufficient antigen presentation → impaired vaccine response."}, {"id": "s2", "type": "receptor", "name": "TCR/CD3 complex", "phase": "recognition", "desc": "TCR αβ + CD3 γδεζ transmits the signal", "function": "The TCR recognises antigen, but CD3 chains (γ, δ, ε, ζ) contain ITAMs (immunoreceptor tyrosine-based activation motifs) that are the actual signalling units. Each ζ chain has 3 ITAMs; 10 ITAMs total allow signal amplification.", "upstream": "Antigen-MHC engagement", "downstream": ["Lck", "CD3 ITAM phosphorylation"], "ifAbsent": "No signal transduction. TCR can bind antigen but cannot transmit the signal inward. SCID can result from CD3 chain mutations.", "clinical": "CD3ζ chain deficiency → immunodeficiency. CD3 mutations cause various forms of SCID."}, {"id": "s3", "type": "kinase", "name": "Lck", "phase": "proximal signalling", "desc": "Src-family kinase phosphorylates CD3 ITAMs", "function": "Lck (lymphocyte-specific protein tyrosine kinase) is brought into proximity with CD3 by the CD4 or CD8 co-receptor. Lck phosphorylates the ITAMs on CD3 chains, creating docking sites for ZAP-70.", "upstream": "CD4/CD8 co-receptor engagement", "downstream": ["CD3 ITAM phosphorylation", "ZAP-70"], "ifAbsent": "ITAMs are not phosphorylated. ZAP-70 cannot be recruited. T-cell activation fails completely. Lck deficiency causes SCID.", "clinical": "Lck mutations → SCID. CD4/CD8 co-receptor defects impair but do not abolish signalling (redundancy)."}, {"id": "s4", "type": "adaptor", "name": "CD3 ITAM phosphorylation", "phase": "proximal signalling", "desc": "ITAMs become docking sites for ZAP-70", "function": "Phosphorylated ITAMs (on CD3ζ especially) serve as docking sites for the SH2 domains of ZAP-70. This is the critical amplification step, 10 ITAMs provide enormous signal amplification and sensitivity.", "upstream": "Lck kinase activity", "downstream": ["ZAP-70 recruitment", "ZAP-70 activation"], "ifAbsent": "ZAP-70 has no docking site. Signal cannot propagate despite TCR engagement.", "clinical": "ITAM mutations in CD3ζ → impaired T-cell activation. Some tumours downregulate CD3ζ."}, {"id": "s5", "type": "kinase", "name": "ZAP-70", "phase": "proximal signalling", "desc": "Syk-family kinase: the central signal amplifier", "function": "ZAP-70 binds phosphorylated ITAMs via its tandem SH2 domains. Lck then phosphorylates ZAP-70, activating it. Active ZAP-70 phosphorylates the adaptor proteins LAT and SLP-76, forming the signalosome.", "upstream": "Phosphorylated CD3 ITAMs", "downstream": ["LAT", "SLP-76", "Signalosome formation"], "ifAbsent": "T-cell activation fails. Signal cannot propagate from the TCR. ZAP-70 deficiency causes a form of SCID with specific absence of CD8+ T cells.", "clinical": "ZAP-70 mutations → SCID (T−B+ NK+ with absent CD8+ T cells). ZAP-70 expression in CLL indicates unmutated IGHV and worse prognosis."}, {"id": "s6", "type": "adaptor", "name": "LAT / SLP-76", "phase": "signalosome", "desc": "Adaptor proteins form the signalosome hub", "function": "LAT (linker for activation of T cells) and SLP-76 are transmembrane and cytosolic adaptors respectively. When phosphorylated by ZAP-70, they nucleate a large signalling complex (signalosome) that recruits PLCγ1, PI3K, and other enzymes.", "upstream": "ZAP-70 kinase activity", "downstream": ["PLCγ1", "PI3K/AKT/mTOR", "Three transcription factor branches"], "ifAbsent": "Signalosome cannot form. All downstream signalling is abolished. LAT deficiency causes a combined immunodeficiency.", "clinical": "LAT mutations → SCID-like disease. SLP-76 deficiency → bleeding disorders and T-cell defects."}, {"id": "s7", "type": "adaptor", "name": "PLCγ1", "phase": "signalosome", "desc": "Generates IP3 and DAG, the second messengers", "function": "Phospholipase Cγ1 hydrolyses PIP2 into IP3 and DAG. These two second messengers diverge into the calcium/calcineurin/NFAT pathway and the PKCθ/CBM/NF-κB + Ras-MAPK/AP-1 pathways.", "upstream": "LAT/SLP-76 signalosome", "downstream": ["IP3 → Ca²⁺ → Calcineurin → NFAT", "DAG → PKCθ → CBM → NF-κB", "DAG → RasGRP → Ras-MAPK → AP-1"], "ifAbsent": "No second messenger generation. All three transcription factor pathways fail.", "clinical": "PLCγ1 deficiency → severe T-cell immunodeficiency. Activating mutations → T-cell lymphoma."}, {"id": "s8a", "type": "transcription", "name": "NFAT", "phase": "transcription", "desc": "Calcium → calcineurin → NFAT dephosphorylation → nuclear entry", "function": "IP3 releases Ca²⁺ from ER. Calcium activates calcineurin (a phosphatase). Calcineurin dephosphorylates NFAT, allowing nuclear translocation. NFAT drives IL-2 transcription.", "upstream": "IP3 → Ca²⁺ release", "downstream": ["IL-2 transcription", "T-cell activation genes"], "ifAbsent": "No IL-2 production. T-cell activation is severely impaired.", "clinical": "Cyclosporin and tacrolimus (calcineurin inhibitors) block NFAT → immunosuppression for transplantation."}, {"id": "s8b", "type": "transcription", "name": "NF-κB", "phase": "transcription", "desc": "DAG → PKCθ → CBM → IKK → NF-κB", "function": "DAG activates PKCθ → CBM complex (CARMA1-BCL10-MALT1) → IKK activation → IκB degradation → NF-κB nuclear entry. NF-κB drives survival and inflammatory gene expression.", "upstream": "DAG → PKCθ → CBM complex", "downstream": ["Survival genes", "Inflammatory cytokines", "Anti-apoptotic genes"], "ifAbsent": "T cells cannot survive activation. No inflammatory gene expression.", "clinical": "Chronic NF-κB activation → chronic inflammation, lymphoproliferation, cancer. CBM mutations → lymphoma."}, {"id": "s8c", "type": "transcription", "name": "AP-1", "phase": "transcription", "desc": "DAG → RasGRP → Ras → MAPK → Fos/Jun → AP-1", "function": "DAG activates RasGRP → Ras → Raf-MEK-ERK MAPK → Fos/Jun expression → AP-1. AP-1 cooperates with NFAT and NF-κB to drive IL-2 and activation genes.", "upstream": "DAG → RasGRP → Ras-MAPK cascade", "downstream": ["IL-2 transcription", "Proliferation genes"], "ifAbsent": "Impaired IL-2 production and T-cell proliferation.", "clinical": "MAPK pathway dysregulation → cancer (Ras mutations)."}, {"id": "s9", "type": "output", "name": "IL-2 + Activation Genes", "phase": "output", "desc": "NFAT + NF-κB + AP-1 cooperatively drive transcription", "function": "The three transcription factors bind cooperatively to the IL-2 promoter and other activation genes. CD28 co-stimulation amplifies this through PI3K-AKT-mTOR.", "upstream": "NFAT + NF-κB + AP-1 nuclear translocation", "downstream": ["T-cell activation", "Proliferation", "Effector differentiation"], "ifAbsent": "No IL-2, no proliferation. T cells enter anergy if TCR signal occurs without co-stimulation.", "clinical": "IL-2 therapy (aldesleukin) for melanoma. Anti-IL-2R (basiliximab) for transplant rejection."}, {"id": "s10", "type": "output", "name": "T-cell Activation", "phase": "output", "desc": "Proliferation, differentiation, effector function", "function": "The integrated signal drives clonal expansion, differentiation into effector subsets (Th1, Th2, Th17, Tfh, Treg), and acquisition of effector functions.", "upstream": "IL-2 and activation gene transcription", "downstream": ["Effector T cells", "Memory T cells"], "ifAbsent": "No adaptive immune response. Checkpoint inhibitors (anti-PD-1, anti-CTLA-4) restore T-cell activation in cancer.", "clinical": "Checkpoint inhibitors restore T-cell activation in cancer. Calcineurin inhibitors prevent T-cell activation in transplantation."}], "tcrPerturbations": [{"id": "p1", "question": "What happens if ZAP-70 is absent?", "target": "ZAP-70 (step 5)", "chain": ["CD3 ITAMs may still be phosphorylated by Lck", "But ZAP-70 cannot bind, no kinase to phosphorylate LAT/SLP-76", "The signalosome cannot form", "PLCγ1 is not activated, no IP3 or DAG production", "All three transcription factor branches fail: NFAT, NF-κB, and AP-1", "No IL-2 transcription, no proliferation, no effector differentiation", "T-cell activation and development are defective"], "clinical": "Clinical link: ZAP-70 deficiency causes SCID (T−B+NK+ with absent CD8+ T cells). In CLL, ZAP-70 expression indicates unmutated IGHV and worse prognosis."}, {"id": "p2", "question": "What happens if CTLA-4 is engaged instead of CD28?", "target": "Co-stimulation (CD28 vs CTLA-4)", "chain": ["CTLA-4 is upregulated after T-cell activation and competes with CD28 for CD80/CD86", "CTLA-4 has higher affinity, wins the competition", "CD28 co-stimulation is reduced or abolished", "PI3K-AKT-mTOR signalling is diminished", "T-cell activation threshold rises", "Without sufficient co-stimulation, T cells may enter anergy", "Net effect: immune response is dampened, tolerance is promoted"], "clinical": "Abatacept (CTLA-4-Ig) mimics CTLA-4 → immunosuppression in RA. Ipilimumab (anti-CTLA-4) releases the brake → melanoma immunotherapy."}, {"id": "p3", "question": "What happens if NF-κB becomes chronically activated?", "target": "NF-κB (step 8b)", "chain": ["NF-κB stays in the nucleus instead of cycling back", "Anti-apoptotic genes (Bcl-xL, Bcl-2, c-FLIP) are continuously expressed", "Survival signals maintain T cells beyond their normal lifespan", "Inflammatory cytokines (IL-6, TNF, IL-1β) are persistently produced", "The normal contraction phase (apoptosis of effector cells) fails", "Chronic inflammation develops, tissue damage accumulates", "Lymphoproliferation may progress to lymphoma in some contexts"], "clinical": "Chronic NF-κB drives RA, IBD, lymphoma. CBM mutations found in lymphomas. Anti-NF-κB: corticosteroids, JAK inhibitors, bortezomib."}], "il6Chain": [{"label": "Source", "value": "Macrophage / Dendritic Cell", "desc": "Activated by PAMPs or DAMPs"}, {"label": "Cytokine", "value": "IL-6", "desc": "Produced via TLR/NF-κB activation"}, {"label": "Receptor", "value": "IL-6R (membrane) + gp130 (ubiquitous)", "desc": "Classical + trans-signalling"}, {"label": "Signalling", "value": "JAK1/JAK2 → STAT3", "desc": "Classical and trans-signalling pathways"}, {"label": "Target Cells", "value": "Hepatocytes, T cells, B cells, macrophages", "desc": "Almost all cells express gp130"}, {"label": "Cell State", "value": "Acute-phase response, plasma cell differentiation, Th17/Treg shift", "desc": "STAT3 drives survival and differentiation"}, {"label": "Tissue Effect", "value": "CRP production, inflammation, bone remodelling, tissue repair", "desc": "Liver produces CRP, clinical biomarker"}, {"label": "Clinical Phenotype", "value": "RA, Castleman disease, cytokine storm (COVID-19)", "desc": "Same cytokine, different diseases"}], "modules": [{"letter": "A", "title": "Molecular Immunology", "desc": "Receptor architecture, kinase cascades, transcription factors, signal amplification, feedback loops", "layer": "2, Mechanism", "status": "active"}, {"letter": "B", "title": "Cellular State Transitions", "desc": "Activation, differentiation, state changes. Naive → effector → memory. Exhaustion, senescence, tissue-residency", "layer": "2, Mechanism", "status": "planned"}, {"letter": "C", "title": "Cytokine Networks", "desc": "Source → cytokine → receptor → signalling → target → cell state → tissue effect → clinical phenotype", "layer": "2, Mechanism", "status": "active"}, {"letter": "D", "title": "Control Theory", "desc": "Positive feedback, negative feedback, failure of resolution. Why inflammation becomes chronic", "layer": "3, System", "status": "planned"}, {"letter": "E", "title": "Immunological Synapses", "desc": "Cell-cell communication, co-stimulation, inhibitory receptors, checkpoint pathways", "layer": "3, System", "status": "planned"}, {"letter": "F", "title": "Tissue Immunology", "desc": "Bone marrow, thymus, lymph node, spleen, gut, lung, skin, liver, tumour microenvironment", "layer": "4, Dynamics", "status": "planned"}, {"letter": "G", "title": "Immunometabolism", "desc": "Glycolysis, OXPHOS, fatty acid oxidation, mTOR, AMPK, HIF-1α, metabolic reprogramming", "layer": "4, Dynamics", "status": "planned"}, {"letter": "H", "title": "Immunogenetics & Epigenetics", "desc": "HLA, V(D)J, somatic hypermutation, trained immunity, chromatin accessibility, GWAS", "layer": "4, Dynamics", "status": "planned"}, {"letter": "I", "title": "Immunopathology", "desc": "Tolerance breakdown, hypersensitivity types II–IV, mechanism → tissue → pathology → biomarker", "layer": "5, Disease", "status": "planned"}, {"letter": "J", "title": "Cancer Immunology", "desc": "Neoantigens, immune editing, escape mechanisms, checkpoint signalling, tumour metabolism", "layer": "5, Disease", "status": "planned"}, {"letter": "K", "title": "Therapeutic Immunology", "desc": "Drug → target → pathway → cell → tissue → disease → biomarker → outcome → adverse effect", "layer": "6, Therapy", "status": "planned"}, {"letter": "L", "title": "Clinical Immunology", "desc": "Patient → symptoms → phenotype → biomarkers → mechanism → diagnosis → treatment → response", "layer": "7, Evidence", "status": "planned"}, {"letter": "M", "title": "Clinical Trials as Experiments", "desc": "Biological hypothesis → target → therapy → trial → outcome. Why trials fail and what it means", "layer": "7, Evidence", "status": "planned"}, {"letter": "N", "title": "Precision Immunology", "desc": "Genome + phenotype + microbiome + age + environment → patient immune state → predict response", "layer": "8, Patient", "status": "planned"}, {"letter": "O", "title": "AI for Immunology", "desc": "Literature → KG → multi-omics → AI prediction. AI correlation ≠ biological mechanism", "layer": "9, AI", "status": "planned"}]};
